// Single bytes CPython cp932 maps into the private use area that WHATWG Shift_JIS rejects
var cp932Singles = map[byte]rune{0xa0: 0xf8f0, 0xfd: 0xf8f1, 0xfe: 0xf8f2, 0xff: 0xf8f3}

// Code ranges WHATWG GBK maps that CPython gbk rejects
var gbkRejected = [][2]uint16{{0xa2e3, 0xa2e3}, {0xa3a0, 0xa3a0}, {0xa8bf, 0xa8bf}, {0xa989, 0xa995}, {0xfe50, 0xfe50},
	{0xfe54, 0xfe58}, {0xfe5a, 0xfe60}, {0xfe62, 0xfe65}, {0xfe68, 0xfe6b}, {0xfe6e, 0xfe75}, {0xfe77, 0xfe7d},
	{0xfe80, 0xfe8f}, {0xfe92, 0xfe9f}}

// CPython cp932 answer for a unit where it departs from WHATWG Shift_JIS, user defined rows mapping to private use
func cp932Override(b []byte) (rune, int) {
	if r, ok := cp932Singles[b[0]]; ok && len(b) == 1 {
		return r, 1
	}
	if len(b) == 2 && b[0] >= 0xf0 && b[0] <= 0xf9 && b[1] >= 0x40 && b[1] <= 0xfc && b[1] != 0x7f {
		trail := int(b[1]) - 0x40
		if b[1] >= 0x80 {
			trail--
		}
		return rune(0xe000 + int(b[0]-0xf0)*188 + trail), 2
	}
	return 0, 0
}

// CPython gbk answer for one unit where it departs from WHATWG GBK, a negative size rejecting it
func gbkOverride(b []byte) (rune, int) {
	if b[0] == 0x80 {
		return utf8.RuneError, -1
	}
	if len(b) == 2 && codeInRanges(uint16(b[0])<<8|uint16(b[1]), gbkRejected) {
		return utf8.RuneError, -1
	}
	return 0, 0
}

// Reports whether a double byte code falls in one of the inclusive ranges
func codeInRanges(code uint16, ranges [][2]uint16) bool {
	for _, r := range ranges {
		if code >= r[0] && code <= r[1] {
			return true
		}
	}
	return false
}

// Decoder CPython uses for a cp name, nil when CPython has no codec for that code page
func pyCodePageDecoder(cp int) codePageDecoder {
	if table, ok := pyCodePageTables[cp]; ok {
		runes := []rune(table)
		return func(data []byte) (string, bool, error) {
			out := make([]rune, len(data))
			for i, b := range data {
				if runes[b] == 0xfffe {
					return "", false, nil
				}
				out[i] = runes[b]
			}
			return string(out), true, nil
		}
	}
	switch cp {
	case 65001:
		return func(data []byte) (string, bool, error) { return string(data), utf8.Valid(data), nil }
	case 932:
		return cjkCodePageDecoder(japanese.ShiftJIS, cp932Override)
	case 936:
		return cjkCodePageDecoder(simplifiedchinese.GBK, gbkOverride)
	case 949:
		return cjkCodePageDecoder(korean.EUCKR, func([]byte) (rune, int) { return 0, 0 })
	case 950:
		return cjkCodePageDecoder(traditionalchinese.Big5, cp950Override)
	case 1361:
		return func(data []byte) (string, bool, error) {
			text, ok := johabDecode(data)
			return text, ok, nil
		}
	}
	return nil
}

// CPython cp950 answer for one unit where it departs from WHATWG Big5, a negative size rejecting it
func cp950Override(b []byte) (rune, int) {
	if len(b) != 2 {
		return 0, 0
	}
	code := uint16(b[0])<<8 | uint16(b[1])
	if codeInRanges(code, cp950Rejected) {
		return utf8.RuneError, -1
	}
	offset := 0
	for _, r := range cp950RemapRanges {
		if code >= r[0] && code <= r[1] {
			return cp950RemapRunes[offset+int(code-r[0])], 2
		}
		offset += int(r[1]-r[0]) + 1
	}
	return 0, 0
}

// Strict double byte decoder, one or two bytes per character, the override answering first when it knows the unit
func cjkCodePageDecoder(enc encoding.Encoding, override func(b []byte) (rune, int)) codePageDecoder {
	return func(data []byte) (string, bool, error) {
		dec := enc.NewDecoder()
		unit := func(b []byte) (rune, bool) {
			if r, size := override(b); size != 0 {
				return r, size > 0
			}
			out, err := dec.Bytes(b)
			if err != nil {
				return 0, false
			}
			runes := []rune(string(out))
			if len(runes) != 1 || runes[0] == utf8.RuneError {
				return 0, false
			}
			return runes[0], true
		}
		var sb strings.Builder
		for i := 0; i < len(data); {
			if r, ok := unit(data[i : i+1]); ok {
				sb.WriteRune(r)
				i++
				continue
			}
			if i+1 < len(data) {
				if r, ok := unit(data[i : i+2]); ok {
					sb.WriteRune(r)
					i += 2
					continue
				}
			}
			return "", false, nil
		}
		return sb.String(), true, nil
	}
}

// Johab text with algorithmic hangul and the KS X 1001 rows for symbols and hanja, false on any invalid unit
func johabDecode(data []byte) (string, bool) {
	ksx := korean.EUCKR.NewDecoder()
	var sb strings.Builder
	for i := 0; i < len(data); {
		c := data[i]
		if c < 0x80 {
			sb.WriteByte(c)
			i++
			continue
		}
		if i+1 >= len(data) {
			return "", false
		}
		c2 := data[i+1]
		if c < 0xd8 {
			a, b, d := (c>>2)&0x1f, ((c<<3)|(c2>>5))&0x1f, c2&0x1f
			cho, jung, jong := johabIdxCho[a], johabIdxJung[b], johabIdxJong[d]
			if cho == johabNone || jung == johabNone || jong == johabNone {
				return "", false
			}
			switch {
			case cho == johabFill && jung == johabFill && jong == johabFill:
				sb.WriteRune(0x3000)
			case cho == johabFill && jung == johabFill:
				sb.WriteRune(0x3100 | rune(johabJamoJong[d]))
			case cho == johabFill && jong == johabFill:
				sb.WriteRune(0x3100 | rune(johabJamoJung[b]))
			case cho == johabFill:
				return "", false
			case jung == johabFill && jong == johabFill:
				sb.WriteRune(0x3100 | rune(johabJamoCho[a]))
			case jung == johabFill:
				return "", false
			default:
				final := 0
				if jong != johabFill {
					final = int(jong)
				}
				sb.WriteRune(rune(0xac00 + int(cho)*588 + int(jung)*28 + final))
			}
			i += 2
			continue
		}
		if c == 0xdf || c > 0xf9 || c2 < 0x31 || (c2 >= 0x80 && c2 < 0x91) || c2&0x7f == 0x7f || (c == 0xda && c2 >= 0xa1 && c2 <= 0xd3) {
			return "", false
		}
		var t1, t2 byte
		if c < 0xe0 {
			t1 = 2 * (c - 0xd9)
		} else {
			t1 = 2*c - 0x97
		}
		if c2 < 0x91 {
			t2 = c2 - 0x31
		} else {
			t2 = c2 - 0x43
		}
		if t2 < 0x5e {
			t1 += 0x21
		} else {
			t1 += 0x22
			t2 -= 0x5e
		}
		t2 += 0x21
		if t1 < 0x21 || t1 > 0x7e || t2 < 0x21 || t2 > 0x7e {
			return "", false
		}
		out, err := ksx.Bytes([]byte{t1 | 0x80, t2 | 0x80})
		runes := []rune(string(out))
		if err != nil || len(runes) != 1 || runes[0] == utf8.RuneError {
			return "", false
		}
		sb.WriteRune(runes[0])
		i += 2
	}
	return sb.String(), true
}

